from mod import _filter_dict_recursively


def test_nested_mismatch_does_not_crash():
    a = {"user": {"id": 1}}
    b = {"user": {"id": "1"}}  # scalar under same key shape
    assert _filter_dict_recursively(a, b)

def test_type_mismatch_scalar_dict():
    assert _filter_dict_recursively({"a": {"x": 1}}, {"a": {"x": 2}})
    # crash case: dict vs scalar
    out = _filter_dict_recursively({"a": {"x": 1}}, {"a": 5})
    assert out == {"a": {"x": 1}}
